import json

def process_payment(idempotency_key, amount):
    cached_receipt = redis.get(idempotency_key)
    if cached_receipt is not None:
        if isinstance(cached_receipt, (bytes, bytearray)):
            return json.loads(cached_receipt.decode("utf-8"))
        if isinstance(cached_receipt, str):
            return json.loads(cached_receipt)
        return cached_receipt

    receipt = stripe.Charge.create(amount=amount)
    redis.set(idempotency_key, json.dumps(receipt, separators=(",", ":")), nx=True)
    return receipt
